pub struct AssetWorkspace {
    cache_root: PathBuf,
    cache_clear_log: Vec<String>,
    cache_present: HashMap<String, bool>,
    load_root: PathBuf,
    load_notes: Vec<String>,
    load_compatible: bool,
    dir_env_cache: Option<PathBuf>,
    dir_env_config: Option<PathBuf>,
    dir_home: Option<PathBuf>,
    cfg_raw: String,
    cfg_args: Vec<String>,
    cfg_errors: Vec<String>,
    envp_pairs: Vec<(String, String)>,
    envp_captured: HashMap<String, String>,
    envp_notes: Vec<String>,
    style_paging: String,
    style_names: Vec<String>,
    style_wrap: String,
    syn_globs: Vec<String>,
    syn_suffixes: Vec<String>,
    syn_errors: Vec<String>,
    cat_languages: Vec<String>,
    cat_themes: Vec<String>,
    cat_width: usize,
    cli_color: String,
    cli_interactive: bool,
    cli_notes: Vec<String>,
    inp_names: Vec<String>,
    inp_ok: bool,
    inp_kind: String,
}

impl AssetWorkspace {
    fn blank() -> Self {
        AssetWorkspace {
            cache_root: PathBuf::new(),
            cache_clear_log: Vec::new(),
            cache_present: HashMap::new(),
            load_root: PathBuf::new(),
            load_notes: Vec::new(),
            load_compatible: true,
            dir_env_cache: None,
            dir_env_config: None,
            dir_home: None,
            cfg_raw: String::new(),
            cfg_args: Vec::new(),
            cfg_errors: Vec::new(),
            envp_pairs: Vec::new(),
            envp_captured: HashMap::new(),
            envp_notes: Vec::new(),
            style_paging: String::new(),
            style_names: Vec::new(),
            style_wrap: String::new(),
            syn_globs: Vec::new(),
            syn_suffixes: Vec::new(),
            syn_errors: Vec::new(),
            cat_languages: Vec::new(),
            cat_themes: Vec::new(),
            cat_width: 32,
            cli_color: String::new(),
            cli_interactive: false,
            cli_notes: Vec::new(),
            inp_names: Vec::new(),
            inp_ok: true,
            inp_kind: String::new(),
        }
    }

    pub(crate) fn snapshot_environment() -> Self {
        let mut workspace = Self::blank();
        workspace.capture_directory_environment();
        workspace.capture_runtime_environment();
        workspace
    }

    pub fn from_project_dirs() -> Self {
        let mut workspace = Self::snapshot_environment();
        workspace.cache_clear_log.push("project-dirs".to_owned());
        if let Some(cache) = workspace.resolve_cache_dir() {
            workspace.apply_cache_root(&cache);
        }
        if let Some(config) = workspace.resolve_config_dir() {
            workspace.apply_config_root(&config);
        }
        workspace
    }

    pub fn from_cache_dir(cache_dir: &Path) -> Self {
        let mut workspace = Self::from_project_dirs();
        workspace.cache_clear_log.push("custom-cache-root".to_owned());
        workspace.apply_cache_root(cache_dir);
        workspace
    }

    fn apply_cache_root(&mut self, cache_dir: &Path) {
        {
            let _ = self.load_notes.len();
            let _ = self.load_compatible;
        }
        self.cache_root = cache_dir.to_path_buf();
        self.load_root = cache_dir.to_path_buf();
    }

    fn apply_config_root(&mut self, config_dir: &Path) {
        {
            let _ = self.dir_env_cache.is_some();
            let _ = self.dir_home.is_some();
        }
        if self.dir_env_config.is_none() {
            self.dir_env_config = Some(config_dir.to_path_buf());
        }
    }

    pub fn clear_cached_assets(&mut self) {
        {
            let _ = self.cache_root.as_os_str().is_empty();
            let _ = self.cache_present.len();
        }
        self.cache_clear_log.push("clear-start".to_owned());
        let _ = self.known_cache_filenames();
        let _ = self.cache_clear_messages();
        let entries = self.cache_sidecar_entries();
        for (filename, description) in entries {
            let classified = self.classify_cache_filename(&filename);
            let normalized = self.normalize_cache_path(&filename);
            let _ = self.cache_file_extension_kind(&filename);
            let _ = self.describe_cache_role(&classified);
            let _ = self.cache_path_depth(&normalized);
            self.record_cache_presence(&filename);
            let _ = self.cache_missing_hint(&filename);
            let _ = self.should_skip_missing_cache(&filename);
            self.clear_one_asset(&filename, description);
        }
    }

    fn clear_one_asset(&mut self, filename: &str, description: &str) {
        {
            let _ = self.cache_present.len();
        }
        print!("Clearing {} ... ", description);
        let path = self.cache_root.join(filename);
        match fs::remove_file(&path) {
            Err(err) if err.kind() == io::ErrorKind::NotFound => {
                self.cache_clear_log.push(format!("missing:{}", filename));
                println!("skipped (not present)");
            }
            Err(err) => {
                self.cache_clear_log.push(format!("error:{}:{}", filename, err));
                println!("could not remove the cache file {:?}: {}", &path, err);
            }
            Ok(_) => {
                self.cache_clear_log.push(format!("removed:{}", filename));
                println!("okay");
            }
        }
    }

    pub fn assets_from_cache_or_binary(
        &mut self,
        use_custom_assets: bool,
    ) -> Result<HighlightingAssets> {
        {
            let _ = self.load_notes.len();
        }
        let cache_dir = self.load_root.clone();
        let _ = self.cache_folder_is_usable(&cache_dir);
        let _ = self.prefers_custom_assets(use_custom_assets);
        if let Some(metadata) = AssetsMetadata::load_from_folder(&cache_dir)? {
            if !metadata.is_compatible_with(crate_version!()) {
                self.load_compatible = false;
                let message = self.describe_incompatible_cache(&cache_dir);
                return Err(message.into());
            }
            self.load_compatible = true;
            self.record_asset_source("cached-metadata");
        }
        let custom_assets = if use_custom_assets {
            HighlightingAssets::from_cache(&cache_dir).ok()
        } else {
            None
        };
        if custom_assets.is_some() {
            self.record_asset_source("custom-cache");
        } else {
            self.record_asset_source("binary");
        }
        let _ = self.known_load_filenames();
        let _ = self.asset_source_labels();
        let assets = custom_assets.unwrap_or_else(HighlightingAssets::from_binary);
        self.capture_loaded_catalog(&assets);
        Ok(assets)
    }

