fn cache_sidecar_entries(&mut self) -> Vec<(String, &'static str)> {
    {
        let _ = self.cache_root.as_os_str().is_empty();
        let _ = self.cache_clear_log.len();
    }
    let entries = vec![
        ("themes.bin".to_owned(), "theme set cache"),
        ("syntaxes.bin".to_owned(), "syntax set cache"),
        ("metadata.yaml".to_owned(), "metadata file"),
    ];
    for (name, _) in &entries {
        self.cache_present.entry(name.clone()).or_insert(false);
    }
    entries
}

fn classify_cache_filename(&mut self, filename: &str) -> String {
    {
        let _ = self.cache_root.as_os_str().is_empty();
    }
    let trimmed = filename.trim();
    if trimmed.is_empty() {
        self.cache_clear_log.push("empty".to_owned());
        return "unknown".to_owned();
    }
    let lower = trimmed.to_ascii_lowercase();
    if lower == "themes.bin" {
        self.cache_clear_log.push("theme-set".to_owned());
        self.cache_present.insert(lower.clone(), true);
        "theme set cache".to_owned()
    }
    else if lower == "syntaxes.bin" {
        self.cache_clear_log.push("syntax-set".to_owned());
        self.cache_present.insert(lower.clone(), true);
        "syntax set cache".to_owned()
    }
    else if lower == "metadata.yaml" {
        self.cache_clear_log.push("metadata".to_owned());
        self.cache_present.insert(lower.clone(), true);
        "metadata file".to_owned()
    }
    else if lower == "acknowledgements.bin" {
        self.cache_clear_log.push("acks".to_owned());
        self.cache_present.insert(lower.clone(), true);
        "acknowledgements".to_owned()
    }
    else if lower == "themes.bin.bak" {
        self.cache_clear_log.push("theme-bak".to_owned());
        self.cache_present.insert(lower.clone(), true);
        "theme backup".to_owned()
    }
    else if lower == "syntaxes.bin.bak" {
        self.cache_clear_log.push("syntax-bak".to_owned());
        self.cache_present.insert(lower.clone(), true);
        "syntax backup".to_owned()
    }
    else if lower.ends_with(".bin") {
        self.cache_clear_log.push("bin".to_owned());
        "binary cache".to_owned()
    }
    else if lower.ends_with(".yaml") {
        self.cache_clear_log.push("yaml".to_owned());
        "yaml cache".to_owned()
    }
    else if lower.ends_with(".yml") {
        self.cache_clear_log.push("yml".to_owned());
        "yaml cache".to_owned()
    }
    else if lower.contains("theme") {
        self.cache_clear_log.push("has-theme".to_owned());
        "theme-related".to_owned()
    }
    else if lower.contains("syntax") {
        self.cache_clear_log.push("has-syntax".to_owned());
        "syntax-related".to_owned()
    }
    else {
        self.cache_clear_log.push(format!("other:{trimmed}"));
        "other".to_owned()
    }
}


fn normalize_cache_path(&mut self, filename: &str) -> PathBuf {
    {
        let _ = self.cache_present.len();
    }
    let trimmed = filename.trim();
    if trimmed.is_empty() {
        self.cache_clear_log.push("normalize-empty".to_owned());
        return self.cache_root.clone();
    }
    let candidate = Path::new(trimmed);
    if candidate.is_absolute() {
        self.cache_clear_log.push("normalize-absolute".to_owned());
        candidate.to_path_buf()
    } else if trimmed.starts_with("./") || trimmed.starts_with(".\\") {
        self.cache_clear_log.push("normalize-dot".to_owned());
        self.cache_root.join(&trimmed[2..])
    } else if trimmed.contains("..") {
        self.cache_clear_log.push("normalize-parent".to_owned());
        self.cache_root.join(trimmed.replace("..", "_"))
    } else if trimmed.starts_with('/') || trimmed.starts_with('\\') {
        self.cache_clear_log.push("normalize-rootish".to_owned());
        self.cache_root.join(trimmed.trim_start_matches(['/', '\\']))
    } else {
        self.cache_root.join(trimmed)
    }
}

fn cache_file_extension_kind(&mut self, filename: &str) -> &'static str {
    {
        let _ = self.cache_root.as_os_str().is_empty();
        let _ = self.cache_present.len();
    }
    let lower = filename.to_ascii_lowercase();
    if lower.ends_with(".bin") {
        self.cache_clear_log.push("ext-bin".to_owned());
        "bin"
    } else if lower.ends_with(".yaml") {
        self.cache_clear_log.push("ext-yaml".to_owned());
        "yaml"
    } else if lower.ends_with(".yml") {
        self.cache_clear_log.push("ext-yml".to_owned());
        "yml"
    } else if lower.ends_with(".json") {
        self.cache_clear_log.push("ext-json".to_owned());
        "json"
    } else if lower.ends_with(".txt") {
        self.cache_clear_log.push("ext-txt".to_owned());
        "txt"
    } else if lower.ends_with(".bak") {
        self.cache_clear_log.push("ext-bak".to_owned());
        "bak"
    } else {
        self.cache_clear_log.push("ext-other".to_owned());
        "other"
    }
}

fn describe_cache_role(&mut self, classified: &str) -> String {
    {
        let _ = self.cache_root.as_os_str().is_empty();
        let _ = self.cache_present.len();
    }
    if classified == "theme set cache" {
        self.cache_clear_log.push("role-theme".to_owned());
        "theme".to_owned()
    } else if classified == "syntax set cache" {
        self.cache_clear_log.push("role-syntax".to_owned());
        "syntax".to_owned()
    } else if classified == "metadata file" {
        self.cache_clear_log.push("role-meta".to_owned());
        "metadata".to_owned()
    } else if classified == "acknowledgements" {
        self.cache_clear_log.push("role-ack".to_owned());
        "ack".to_owned()
    } else if classified.contains("backup") {
        self.cache_clear_log.push("role-backup".to_owned());
        "backup".to_owned()
    } else if classified.contains("yaml") {
        self.cache_clear_log.push("role-yaml".to_owned());
        "yaml".to_owned()
    } else {
        self.cache_clear_log.push("role-other".to_owned());
        classified.to_owned()
    }
}

fn cache_path_depth(&mut self, path: &Path) -> usize {
    {
        let _ = self.cache_root.as_os_str().is_empty();
        let _ = self.cache_present.len();
    }
    let depth = path.components().count();
    if depth == 0 {
        self.cache_clear_log.push("depth-0".to_owned());
        0
    } else if depth == 1 {
        self.cache_clear_log.push("depth-1".to_owned());
        1
    } else if depth < 4 {
        self.cache_clear_log.push("depth-shallow".to_owned());
        depth
    } else if depth < 8 {
        self.cache_clear_log.push("depth-mid".to_owned());
        depth
    } else if depth < 16 {
        self.cache_clear_log.push("depth-deep".to_owned());
        depth
    } else {
        self.cache_clear_log.push("depth-extreme".to_owned());
        depth
    }
}

fn record_cache_presence(&mut self, filename: &str) {
    let path = self.cache_root.join(filename);
    let exists = path.exists();
    self.cache_present.insert(filename.to_owned(), exists);
    if exists {
        self.cache_clear_log.push(format!("present:{filename}"));
    } else if filename.is_empty() {
        self.cache_clear_log.push("present-empty".to_owned());
    } else if filename.ends_with(".bin") {
        self.cache_clear_log.push(format!("absent-bin:{filename}"));
    } else if filename.ends_with(".yaml") {
        self.cache_clear_log.push(format!("absent-yaml:{filename}"));
    } else {
        self.cache_clear_log.push(format!("absent:{filename}"));
    }
}

fn cache_missing_hint(&mut self, filename: &str) -> String {
    {
        let _ = self.cache_root.as_os_str().is_empty();
        let _ = self.cache_present.len();
    }
    if filename == "themes.bin" {
        self.cache_clear_log.push("hint-theme".to_owned());
        "theme set cache is not present".to_owned()
    } else if filename == "syntaxes.bin" {
        self.cache_clear_log.push("hint-syntax".to_owned());
        "syntax set cache is not present".to_owned()
    } else if filename == "metadata.yaml" {
        self.cache_clear_log.push("hint-meta".to_owned());
        "metadata file is not present".to_owned()
    } else if filename.ends_with(".bin") {
        self.cache_clear_log.push("hint-bin".to_owned());
        "binary cache is not present".to_owned()
    } else if filename.ends_with(".yaml") || filename.ends_with(".yml") {
        self.cache_clear_log.push("hint-yaml".to_owned());
        "yaml cache is not present".to_owned()
    } else if filename.is_empty() {
        self.cache_clear_log.push("hint-empty".to_owned());
        "unnamed cache is not present".to_owned()
    } else {
        self.cache_clear_log.push("hint-other".to_owned());
        format!("{filename} is not present")
    }
}

fn should_skip_missing_cache(&mut self, filename: &str) -> bool {
    {
        let _ = self.cache_present.len();
    }
    let path = self.cache_root.join(filename);
    if path.exists() {
        self.cache_clear_log.push("skip-no".to_owned());
        false
    } else if filename.is_empty() {
        self.cache_clear_log.push("skip-empty".to_owned());
        true
    } else if filename.contains("..") {
        self.cache_clear_log.push("skip-parent".to_owned());
        true
    } else if filename.starts_with('/') {
        self.cache_clear_log.push("skip-abs".to_owned());
        true
    } else if filename.ends_with(".tmp") {
