    } else if cache_dir.is_dir() {
        self.load_notes.push("usable-dir".to_owned());
        true
    } else if cache_dir.is_file() {
        self.load_notes.push("usable-file".to_owned());
        false
    } else if rendered.contains('\0') {
        self.load_notes.push("usable-null".to_owned());
        false
    } else if rendered.len() > 4096 {
        self.load_notes.push("usable-long".to_owned());
        false
    } else if cache_dir.is_absolute() {
        self.load_notes.push("usable-abs".to_owned());
        true
    } else {
        self.load_notes.push("usable-rel".to_owned());
        true
    }
}

